import '@fontsource/roboto/400.css';
import '@fontsource/roboto/500.css';
import '@fontsource/roboto/700.css';
import {
  Alert, AppBar, Avatar, Box, Button, Card, CardActionArea, CardContent, Chip, CircularProgress,
  CssBaseline, Dialog, DialogActions, DialogContent, DialogTitle, Divider, Drawer, FormControl,
  FormControlLabel, IconButton, InputAdornment, InputLabel, LinearProgress, List, ListItemButton,
  ListItemIcon, ListItemText, MenuItem, Paper, Radio, RadioGroup, Select, Snackbar, Stack,
  Table, TableBody, TableCell, TableContainer, TableHead, TableRow, TextField, ThemeProvider,
  Toolbar, Tooltip, Typography, createTheme, useMediaQuery,
} from '@mui/material';
import {
  AddRounded, ArrowBackRounded, BugReportRounded, CheckCircleRounded, CloseRounded,
  DashboardRounded, DarkModeRounded, DescriptionRounded, FolderRounded, HelpOutlineRounded,
  LockRounded, LogoutRounded, MenuRounded, MoreHorizRounded, SearchRounded, TuneRounded,
  UploadFileRounded,
} from '@mui/icons-material';

const drawerWidth = 272;
const theme = createTheme({
  palette: {
    mode: 'light',
    primary: { main: '#5B4EE5', light: '#E9E7FF', dark: '#4338C7', contrastText: '#FFFFFF' },
    secondary: { main: '#006B5D' },
    error: { main: '#BA1A1A' },
    warning: { main: '#8A5A00' },
    success: { main: '#176C2F' },
    background: { default: '#FAF9FF', paper: '#FFFFFF' },
    text: { primary: '#1C1B20', secondary: '#625B71' },
    divider: '#E7E0EC',
  },
  typography: { fontFamily: 'Roboto, Arial, sans-serif', h4: { fontWeight: 700, letterSpacing: '-0.025em' }, h5: { fontWeight: 700, letterSpacing: '-0.018em' }, h6: { fontWeight: 700 } },
  shape: { borderRadius: 16 },
  components: {
    MuiButton: { styleOverrides: { root: { borderRadius: 20, textTransform: 'none', fontWeight: 700, boxShadow: 'none' } } },
    MuiCard: { styleOverrides: { root: { border: '1px solid #E7E0EC', boxShadow: 'none', borderRadius: 20 } } },
    MuiPaper: { styleOverrides: { rounded: { borderRadius: 20 } } },
    MuiTextField: { defaultProps: { size: 'small', variant: 'outlined' } },
  },
});

type Status = 'new' | 'acknowledged' | 'in_progress' | 'resolved' | 'closed';
type Priority = 'low' | 'medium' | 'high' | 'critical';
type View = 'Dashboard' | 'Reports' | 'Projects';
type User = { id: string; username: string; email: string; displayName: string; isPlatformAdmin: boolean };
type Organization = { id: string; name: string; slug: string; role: string };
type Project = { id: string; name: string; slug: string; description?: string | null; color: string; openReportCount: number };
type Report = { id: string; sequenceNumber: number; title: string; status: Status; priority: Priority; updatedAt: string; dueAt?: string | null; projectId: string; projectName: string; reporterName: string; assigneeName?: string | null; labels: string[] };
type Session = { user: User; organizations: Organization[] };

const statusOrder: Status[] = ['new', 'acknowledged', 'in_progress', 'resolved', 'closed'];
const priorityOrder: Priority[] = ['low', 'medium', 'high', 'critical'];
const statusLabel = (value: Status) => ({ new: 'New', acknowledged: 'Acknowledged', in_progress: 'In progress', resolved: 'Resolved', closed: 'Closed' })[value];
const priorityLabel = (value: Priority) => value[0].toUpperCase() + value.slice(1);
const reportCode = (report: Report) => `BF-${report.sequenceNumber}`;
const roleLabel = (role: string) => role.replaceAll('_', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());

async function api<T>(path: string, options: RequestInit = {}): Promise<T> {
  const response = await fetch(path, { ...options, credentials: 'include', headers: { ...(options.body instanceof FormData ? {} : { 'Content-Type': 'application/json' }), ...(options.headers ?? {}) } });
  if (!response.ok) { const body = await response.json().catch(() => ({ error: 'Unable to complete this request.' })); throw new Error(body.error ?? 'Unable to complete this request.'); }
  if (response.status === 204) return undefined as T;
  return response.json() as Promise<T>;
}

function Brand({ compact = false }: { compact?: boolean }) {
  return <Stack direction="row" alignItems="center" spacing={1.1}><Box sx={{ width: 30, height: 30, display: 'grid', placeItems: 'center', bgcolor: 'primary.main', color: 'primary.contrastText', borderRadius: 2.25, fontWeight: 800, fontSize: 15 }}>B</Box>{!compact && <Typography variant="h6" sx={{ letterSpacing: '-.03em' }}>BugFlow</Typography>}</Stack>;
}
function PriorityDot({ priority }: { priority: Priority }) { const colors: Record<Priority, string> = { critical: '#BA1A1A', high: '#D86F00', medium: '#5B4EE5', low: '#607083' }; return <Box component="span" sx={{ display: 'inline-block', width: 9, height: 9, bgcolor: colors[priority], borderRadius: '50%', flex: '0 0 auto' }} />; }
function StatusChip({ status }: { status: Status }) { const colors: Record<Status, { bg: string; color: string }> = { new: { bg: '#E9E7FF', color: '#4338C7' }, acknowledged: { bg: '#FFF0D6', color: '#8A5200' }, in_progress: { bg: '#DFF7EC', color: '#006C4C' }, resolved: { bg: '#E5E2E9', color: '#48454E' }, closed: { bg: '#E5E2E9', color: '#48454E' } }; const tone = colors[status]; return <Chip label={statusLabel(status)} size="small" sx={{ height: 25, bgcolor: tone.bg, color: tone.color, fontWeight: 700, '& .MuiChip-label': { px: 1.1 } }} />; }
function relativeDate(value: string) { const time = Date.parse(value); if (Number.isNaN(time)) return 'Recently'; const minutes = Math.max(0, Math.floor((Date.now() - time) / 60000)); return minutes < 2 ? 'Just now' : minutes < 60 ? `${minutes}m ago` : minutes < 1440 ? `${Math.floor(minutes / 60)}h ago` : `${Math.floor(minutes / 1440)}d ago`; }

export default function App() {
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  const [authError, setAuthError] = useState('');
  const [authMode, setAuthMode] = useState<'login' | 'request' | 'reset'>(() => new URLSearchParams(window.location.search).get('reset') ? 'reset' : 'login');
  const resetToken = useMemo(() => new URLSearchParams(window.location.search).get('reset') ?? '', []);
  const refreshSession = async () => { const current = await api<Session>('/api/auth/session'); setSession(current); return current; };
  useEffect(() => { api<Session>('/api/auth/session').then(setSession).catch(() => setSession(null)).finally(() => setLoading(false)); }, []);
  const content = loading ? <LoadingScreen /> : !session && authMode === 'request' ? <RequestResetScreen onBack={() => setAuthMode('login')} /> : !session && authMode === 'reset' && resetToken ? <ResetPasswordScreen token={resetToken} onBack={() => { window.history.replaceState({}, '', window.location.pathname); setAuthMode('login'); }} /> : !session ? <LoginScreen error={authError} onReset={() => setAuthMode('request')} onLogin={async (identifier, password) => { setAuthError(''); try { await api('/api/auth/login', { method: 'POST', body: JSON.stringify({ identifier, password }) }); await refreshSession(); } catch (error) { setAuthError(error instanceof Error ? error.message : 'Unable to sign in.'); } }} /> : session.user.isPlatformAdmin && session.organizations.length === 0 ? <OrganizationOnboarding user={session.user} onCreated={refreshSession} /> : <Workspace session={session} onLogout={async () => { await api('/api/auth/logout', { method: 'POST' }); setSession(null); }} />;
  return <ThemeProvider theme={theme}><CssBaseline />{content}</ThemeProvider>;
}

function LoadingScreen() { return <Box sx={{ minHeight: '100vh', display: 'grid', placeItems: 'center', bgcolor: 'background.default' }}><Stack spacing={2} alignItems="center"><Brand /><CircularProgress size={28} /><Typography color="text.secondary">Preparing your workspace…</Typography></Stack></Box>; }
function AuthFrame({ eyebrow, title, copy, children }: { eyebrow: string; title: string; copy: string; children: React.ReactNode }) { return <Box sx={{ minHeight: '100vh', display: 'grid', gridTemplateColumns: { md: '1.08fr .92fr' }, bgcolor: 'background.default' }}><Box sx={{ display: { xs: 'none', md: 'flex' }, flexDirection: 'column', justifyContent: 'space-between', p: { md: 6, lg: 9 }, color: '#FFFFFF', background: 'radial-gradient(circle at 20% 18%, #8176F5 0, rgba(129,118,245,0) 30%), linear-gradient(145deg,#25204E 0%,#4437B4 46%,#6A5BDB 100%)' }}><Brand /><Box sx={{ maxWidth: 530 }}><Typography variant="overline" sx={{ letterSpacing: '.13em', fontWeight: 700, opacity: .8 }}>{eyebrow}</Typography><Typography variant="h2" sx={{ fontWeight: 700, letterSpacing: '-.05em', mt: 1.5, lineHeight: 1.06 }}>{title}</Typography><Typography sx={{ mt: 2.5, maxWidth: 430, color: 'rgba(255,255,255,.78)', fontSize: 18, lineHeight: 1.55 }}>{copy}</Typography></Box><Stack direction="row" spacing={3} sx={{ color: 'rgba(255,255,255,.72)' }}><Typography variant="body2">Governed access</Typography><Typography variant="body2">Private evidence</Typography><Typography variant="body2">Live updates</Typography></Stack></Box><Box sx={{ display: 'grid', placeItems: 'center', p: { xs: 2.5, sm: 5 }, minHeight: { xs: '100vh', md: 'auto' } }}><Box sx={{ width: '100%', maxWidth: 460 }}><Box sx={{ display: { md: 'none' }, mb: 5 }}><Brand /></Box>{children}</Box></Box></Box>; }
function LoginScreen({ onLogin, onReset, error }: { onLogin: (identifier: string, password: string) => Promise<void>; onReset: () => void; error: string }) { const [busy, setBusy] = useState(false); const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setBusy(true); const data = new FormData(event.currentTarget); await onLogin(String(data.get('identifier') ?? ''), String(data.get('password') ?? '')); setBusy(false); }; return <AuthFrame eyebrow="Secure collaboration" title="Clear bugs. Better flow." copy="A trusted space for customers and product teams to report, manage, and resolve issues."><Stack spacing={3}><Box><Typography variant="overline" color="primary.main">Sign in</Typography><Typography variant="h4">Welcome back</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>Use the credentials provided by your administrator.</Typography></Box><Card><CardContent sx={{ p: 3.25 }} component="form" onSubmit={submit}><Stack spacing={2.25}>{error && <Alert severity="error">{error}</Alert>}<TextField required fullWidth label="Username or email" name="identifier" autoComplete="username" /><TextField required fullWidth label="Password" name="password" type="password" autoComplete="current-password" inputProps={{ minLength: 8 }} /><Button type="submit" variant="contained" size="large" disabled={busy} endIcon={busy ? <CircularProgress color="inherit" size={18} /> : undefined}>{busy ? 'Signing in' : 'Sign in'}</Button><Button type="button" variant="text" onClick={onReset}>Forgot password?</Button></Stack></CardContent></Card><Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center' }}>Need access? Ask your organization administrator to create your account.</Typography></Stack></AuthFrame>; }
function RequestResetScreen({ onBack }: { onBack: () => void }) { const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setBusy(true); setError(''); try { await api('/api/auth/password-reset/request', { method: 'POST', body: JSON.stringify({ email: String(new FormData(event.currentTarget).get('email') ?? '') }) }); setMessage('If that account exists, a secure reset link has been sent.'); } catch (err) { setError(err instanceof Error ? err.message : 'Unable to request a reset.'); } finally { setBusy(false); } }; return <AuthFrame eyebrow="Account recovery" title="Get back to flow." copy="We will email a private, one-hour reset link to your BugFlow account."><Stack spacing={3}><Box><Typography variant="overline" color="primary.main">Password recovery</Typography><Typography variant="h4">Reset your password</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>Enter the email address associated with your account.</Typography></Box><Card><CardContent sx={{ p: 3.25 }} component="form" onSubmit={submit}><Stack spacing={2.25}>{error && <Alert severity="error">{error}</Alert>}{message && <Alert severity="success">{message}</Alert>}<TextField required fullWidth label="Email address" type="email" name="email" autoComplete="email"/><Button type="submit" variant="contained" size="large" disabled={busy}>{busy ? 'Sending link…' : 'Email reset link'}</Button><Button type="button" onClick={onBack}>Back to sign in</Button></Stack></CardContent></Card></Stack></AuthFrame>; }
function ResetPasswordScreen({ token, onBack }: { token: string; onBack: () => void }) { const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const password = String(data.get('password') ?? ''); if (password !== String(data.get('confirm') ?? '')) { setError('Passwords do not match.'); return; } setBusy(true); setError(''); try { await api('/api/auth/password-reset/confirm', { method: 'POST', body: JSON.stringify({ token, password }) }); setMessage('Password reset complete. You can now sign in.'); } catch (err) { setError(err instanceof Error ? err.message : 'Unable to reset the password.'); } finally { setBusy(false); } }; return <AuthFrame eyebrow="Account recovery" title="Choose a fresh password." copy="Your reset link is private, single-use, and expires after one hour."><Stack spacing={3}><Box><Typography variant="overline" color="primary.main">Set new password</Typography><Typography variant="h4">Secure your account</Typography></Box><Card><CardContent sx={{ p: 3.25 }} component="form" onSubmit={submit}><Stack spacing={2.25}>{error && <Alert severity="error">{error}</Alert>}{message && <Alert severity="success">{message}</Alert>}<TextField required fullWidth label="New password" type="password" name="password" autoComplete="new-password" inputProps={{ minLength: 12 }}/><TextField required fullWidth label="Confirm password" type="password" name="confirm" autoComplete="new-password" inputProps={{ minLength: 12 }}/><Button type="submit" variant="contained" size="large" disabled={busy || Boolean(message)}>{busy ? 'Updating password…' : 'Update password'}</Button><Button type="button" onClick={onBack}>Back to sign in</Button></Stack></CardContent></Card></Stack></AuthFrame>; }
function OrganizationOnboarding({ user, onCreated }: { user: User; onCreated: () => Promise<unknown> }) { const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const submit = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setBusy(true); setError(''); const f = new FormData(event.currentTarget); try { await api('/api/platform/organizations', { method: 'POST', body: JSON.stringify({ name: String(f.get('name')), slug: String(f.get('slug')).toLowerCase().replace(/[^a-z0-9-]/g, '-'), admin: { username: String(f.get('adminUsername')), email: String(f.get('adminEmail')), displayName: String(f.get('adminName')), password: String(f.get('adminPassword')) } }) }); await onCreated(); } catch (err) { setError(err instanceof Error ? err.message : 'Unable to create organization.'); } finally { setBusy(false); } }; return <Box sx={{ minHeight: '100vh', display: 'grid', placeItems: 'center', p: 2.5, bgcolor: 'background.default' }}><Box maxWidth={760} width="100%"><Stack alignItems="center" spacing={2.5} mb={3}><Brand /><Typography sx={{ textAlign: 'center' }} color="text.secondary">Platform setup</Typography></Stack><Card><CardContent sx={{ p: { xs: 3, sm: 5 } }} component="form" onSubmit={submit}><Stack spacing={3}><Box><Typography variant="h4">Create your first organization</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>You are signed in as {user.displayName}. Create a workspace and its first organization administrator.</Typography></Box>{error && <Alert severity="error">{error}</Alert>}<Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}><TextField required fullWidth label="Organization name" name="name" placeholder="Northstar"/><TextField required fullWidth label="Workspace slug" name="slug" placeholder="northstar" inputProps={{ pattern: '[a-z0-9-]+' }}/></Stack><Divider><Typography variant="overline" color="text.secondary">First organization admin</Typography></Divider><Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}><TextField required fullWidth label="Full name" name="adminName"/><TextField required fullWidth label="Username" name="adminUsername" inputProps={{ minLength: 3 }}/></Stack><Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}><TextField required fullWidth label="Email" type="email" name="adminEmail"/><TextField required fullWidth label="Temporary password" type="password" name="adminPassword" inputProps={{ minLength: 12 }}/></Stack><Button type="submit" variant="contained" size="large" disabled={busy}>{busy ? 'Creating workspace…' : 'Create organization'}</Button></Stack></CardContent></Card></Box></Box>; }

function Workspace({ session, onLogout }: { session: Session; onLogout: () => Promise<void> }) {
  const [activeOrgId, setActiveOrgId] = useState(session.organizations[0]?.id ?? '');
  const [projects, setProjects] = useState<Project[]>([]); const [reports, setReports] = useState<Report[]>([]); const [view, setView] = useState<View>('Dashboard'); const [query, setQuery] = useState(''); const [selected, setSelected] = useState<Report | null>(null); const [showCreate, setShowCreate] = useState(false); const [toast, setToast] = useState(''); const [error, setError] = useState(''); const [drawerOpen, setDrawerOpen] = useState(false);
  const narrow = useMediaQuery(theme.breakpoints.down('md'));
  const activeOrg = session.organizations.find((org) => org.id === activeOrgId) ?? session.organizations[0];
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 3400); };
  const loadWorkspace = async () => { if (!activeOrg) return; setError(''); try { const [projectData, reportData] = await Promise.all([api<{ projects: Project[] }>(`/api/organizations/${activeOrg.id}/projects`), api<{ reports: Report[] }>(`/api/organizations/${activeOrg.id}/reports`)]); setProjects(projectData.projects); setReports(reportData.reports); } catch (err) { setError(err instanceof Error ? err.message : 'Unable to load workspace data.'); } };
  useEffect(() => { void loadWorkspace(); }, [activeOrgId]);
  const visibleReports = useMemo(() => reports.filter((report) => `${reportCode(report)} ${report.title} ${report.projectName} ${report.reporterName} ${(report.labels ?? []).join(' ')}`.toLowerCase().includes(query.toLowerCase())), [reports, query]);
  const openReports = reports.filter((report) => !['resolved', 'closed'].includes(report.status));
  const setStatus = async (report: Report, status: Status) => { try { await api(`/api/reports/${report.id}/status`, { method: 'PATCH', body: JSON.stringify({ status }) }); setReports((items) => items.map((item) => item.id === report.id ? { ...item, status, updatedAt: new Date().toISOString() } : item)); setSelected((item) => item?.id === report.id ? { ...item, status } : item); notify(`${reportCode(report)} moved to ${statusLabel(status)}.`); } catch (err) { notify(err instanceof Error ? err.message : 'Unable to update report status.'); } };
  const createReport = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const f = new FormData(event.currentTarget); try { const created = await api<Report>('/api/reports', { method: 'POST', body: JSON.stringify({ projectId: String(f.get('projectId')), title: String(f.get('title')), description: String(f.get('description')), reproductionSteps: String(f.get('reproductionSteps') || ''), expectedResult: String(f.get('expectedResult') || ''), actualResult: String(f.get('actualResult') || ''), browserDevice: String(f.get('browserDevice') || ''), applicationVersion: String(f.get('applicationVersion') || ''), priority: String(f.get('priority')) }) }); const file = f.get('attachment'); if (file instanceof File && file.size) { const upload = new FormData(); upload.append('file', file); await api(`/api/reports/${created.id}/attachments`, { method: 'POST', body: upload }); } setShowCreate(false); await loadWorkspace(); setView('Reports'); notify('Report created and added to triage.'); } catch (err) { notify(err instanceof Error ? err.message : 'Unable to create report.'); } };
  const postComment = async (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (!selected) return; const f = new FormData(event.currentTarget); const body = String(f.get('body') ?? '').trim(); if (!body) return; try { await api(`/api/reports/${selected.id}/comments`, { method: 'POST', body: JSON.stringify({ body, visibility: f.get('visibility') === 'internal' ? 'internal' : 'customer' }) }); (event.currentTarget as HTMLFormElement).reset(); notify('Update saved.'); } catch (err) { notify(err instanceof Error ? err.message : 'Unable to post the update.'); } };
  const navigation = <Navigation session={session} activeOrg={activeOrg} activeOrgId={activeOrgId} projects={projects} openReports={openReports.length} view={view} onOrgChange={setActiveOrgId} onView={(next) => { setView(next); setDrawerOpen(false); }} onProject={(project) => { setQuery(project.name); setView('Reports'); setDrawerOpen(false); }} onLogout={onLogout} />;
  return <Box sx={{ minHeight: '100vh', bgcolor: 'background.default' }}><Drawer variant={narrow ? 'temporary' : 'permanent'} open={narrow ? drawerOpen : true} onClose={() => setDrawerOpen(false)} ModalProps={{ keepMounted: true }} sx={{ '& .MuiDrawer-paper': { width: drawerWidth, boxSizing: 'border-box', borderRight: '1px solid #E7E0EC', bgcolor: '#FFFBFE' } }}>{navigation}</Drawer><Box component="main" sx={{ ml: { md: `${drawerWidth}px` }, minHeight: '100vh' }}><AppBar position="sticky" color="inherit" elevation={0} sx={{ borderBottom: '1px solid', borderColor: 'divider', bgcolor: 'rgba(255,251,254,.9)', backdropFilter: 'blur(16px)' }}><Toolbar sx={{ minHeight: { xs: 64, sm: 72 }, gap: 1.5, px: { xs: 2, sm: 3 } }}><IconButton onClick={() => setDrawerOpen(true)} sx={{ display: { md: 'none' } }} aria-label="Open navigation"><MenuRounded /></IconButton><TextField value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search reports, projects, people" aria-label="Search reports" sx={{ maxWidth: 480, flex: 1, '& .MuiOutlinedInput-root': { bgcolor: '#F6F2FA', borderRadius: 7 } }} InputProps={{ startAdornment: <InputAdornment position="start"><SearchRounded fontSize="small"/></InputAdornment> }}/><Box sx={{ flexGrow: 1 }} /><Tooltip title="Light Material theme"><IconButton color="primary"><DarkModeRounded fontSize="small" /></IconButton></Tooltip><Button variant="contained" startIcon={<AddRounded />} disabled={!projects.length} onClick={() => setShowCreate(true)} sx={{ display: { xs: 'none', sm: 'inline-flex' } }}>New report</Button><IconButton color="primary" onClick={() => setShowCreate(true)} disabled={!projects.length} sx={{ display: { sm: 'none' } }} aria-label="Create report"><AddRounded /></IconButton></Toolbar></AppBar>{error && <Alert severity="error" sx={{ mx: { xs: 2, sm: 3 }, mt: 2 }}>{error}</Alert>}<Box sx={{ px: { xs: 2, sm: 3, lg: 5 }, py: { xs: 3, sm: 4 }, maxWidth: 1600, mx: 'auto' }}>{view === 'Dashboard' && <Dashboard reports={reports} projects={projects} onViewReports={() => setView('Reports')} onSelect={setSelected} />}{view === 'Reports' && <EnhancedReportsView reports={visibleReports} onSelect={setSelected} onCreate={() => setShowCreate(true)} />}{view === 'Projects' && <ProjectsView projects={projects} onProject={(project) => { setQuery(project.name); setView('Reports'); }} />}</Box></Box><CreateReportDialog open={showCreate} projects={projects} onClose={() => setShowCreate(false)} onCreate={createReport}/><LiveReportPanel report={selected} onClose={() => setSelected(null)} onStatus={setStatus} onSaved={loadWorkspace}/><Snackbar open={Boolean(toast)} autoHideDuration={3400} onClose={() => setToast('')} message={toast} anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }} /></Box>;
}

function Navigation({ session, activeOrg, activeOrgId, projects, openReports, view, onOrgChange, onView, onProject, onLogout }: { session: Session; activeOrg?: Organization; activeOrgId: string; projects: Project[]; openReports: number; view: View; onOrgChange: (id: string) => void; onView: (view: View) => void; onProject: (project: Project) => void; onLogout: () => Promise<void> }) { const nav = [{ label: 'Dashboard', icon: <DashboardRounded /> }, { label: 'Reports', icon: <BugReportRounded />, count: openReports }, { label: 'Projects', icon: <FolderRounded /> }] as const; return <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%', p: 2 }}><Box sx={{ px: 1, pt: .5, pb: 2.5 }}><Brand /></Box><FormControl fullWidth size="small" sx={{ mb: 2.5 }}><Select value={activeOrgId} onChange={(event) => onOrgChange(event.target.value)} aria-label="Switch organization" sx={{ borderRadius: 3, bgcolor: '#F6F2FA', '& .MuiSelect-select': { display: 'flex', alignItems: 'center', gap: 1 } }}>{session.organizations.map((org) => <MenuItem key={org.id} value={org.id}><Avatar sx={{ width: 25, height: 25, bgcolor: 'primary.main', fontSize: 12 }}>{org.name.slice(0,1)}</Avatar>{org.name}</MenuItem>)}</Select></FormControl><List disablePadding sx={{ display: 'grid', gap: .5 }}>{nav.map((item) => <ListItemButton key={item.label} selected={view === item.label} onClick={() => onView(item.label)} sx={{ borderRadius: 3, minHeight: 46, '&.Mui-selected': { bgcolor: '#E9E7FF', color: '#4338C7' }, '&.Mui-selected:hover': { bgcolor: '#E2DFFF' } }}><ListItemIcon sx={{ minWidth: 38, color: 'inherit' }}>{item.icon}</ListItemIcon><ListItemText primary={item.label} primaryTypographyProps={{ fontWeight: view === item.label ? 700 : 500 }} />{'count' in item && <Chip label={item.count} size="small" sx={{ height: 22, bgcolor: view === item.label ? '#D8D4FF' : '#F1EDF5', color: 'inherit' }} />}</ListItemButton>)}</List><Typography variant="overline" color="text.secondary" sx={{ mt: 3, px: 1, fontWeight: 700, letterSpacing: '.1em' }}>Projects</Typography><List disablePadding sx={{ mt: .5, display: 'grid', gap: .25 }}>{projects.slice(0, 7).map((project) => <ListItemButton key={project.id} onClick={() => onProject(project)} sx={{ borderRadius: 2.5, minHeight: 38, px: 1.25 }}><PriorityDot priority="medium" /><Box sx={{ width: 8 }} /><ListItemText primary={project.name} primaryTypographyProps={{ noWrap: true, fontSize: 14 }} /><Typography variant="caption" color="text.secondary">{project.openReportCount}</Typography></ListItemButton>)}</List><Box sx={{ mt: 'auto' }}><Divider sx={{ mb: 1.5 }}/><Stack direction="row" alignItems="center" spacing={1.25} sx={{ px: 1, py: 1 }}><Avatar sx={{ bgcolor: '#6750A4' }}>{session.user.displayName.split(' ').map((part) => part[0]).join('').slice(0,2)}</Avatar><Box minWidth={0} flex={1}><Typography variant="body2" noWrap>{session.user.displayName}</Typography><Typography variant="caption" color="text.secondary" noWrap>{session.user.isPlatformAdmin ? 'Platform administrator' : roleLabel(activeOrg?.role ?? '')}</Typography></Box><Tooltip title="Sign out"><IconButton onClick={() => void onLogout()} size="small"><LogoutRounded fontSize="small" /></IconButton></Tooltip></Stack></Box></Box>; }

function PageHeader({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy: string; action?: React.ReactNode }) { return <Stack direction={{ xs: 'column', sm: 'row' }} alignItems={{ sm: 'flex-end' }} justifyContent="space-between" gap={2.5} sx={{ mb: 3.5 }}><Box><Typography variant="overline" color="primary.main" sx={{ letterSpacing: '.12em' }}>{eyebrow}</Typography><Typography variant="h4">{title}</Typography><Typography color="text.secondary" sx={{ mt: .75, maxWidth: 680 }}>{copy}</Typography></Box>{action}</Stack>; }
function Dashboard({ reports, projects, onViewReports, onSelect }: { reports: Report[]; projects: Project[]; onViewReports: () => void; onSelect: (report: Report) => void }) { const open = reports.filter((report) => !['resolved', 'closed'].includes(report.status)); const critical = open.filter((report) => report.priority === 'critical'); const inProgress = open.filter((report) => report.status === 'in_progress'); const cards = [{ label: 'Open reports', value: open.length, detail: 'Across accessible projects', color: '#E9E7FF', accent: '#4338C7' }, { label: 'Needs attention', value: critical.length, detail: 'Critical priority', color: '#FBEAEA', accent: '#BA1A1A' }, { label: 'In progress', value: inProgress.length, detail: 'Actively being worked', color: '#DFF7EC', accent: '#006C4C' }, { label: 'Projects', value: projects.length, detail: 'Available to you', color: '#FFF0D6', accent: '#7D5700' }]; return <><PageHeader eyebrow="Live workspace" title="Product signal, in one flow." copy="Track customer reports, ownership, and delivery progress from one clear workspace." action={<Button endIcon={<ArrowBackRounded sx={{ transform: 'rotate(180deg)' }} />} onClick={onViewReports}>View all reports</Button>}/><Box sx={{ display: 'grid', gridTemplateColumns: { xs: 'repeat(2,minmax(0,1fr))', lg: 'repeat(4,minmax(0,1fr))' }, gap: 2, mb: 2.5 }}>{cards.map((metric) => <Card key={metric.label} sx={{ bgcolor: metric.color, border: 0 }}><CardContent sx={{ p: 2.25, '&:last-child': { pb: 2.25 } }}><Typography variant="body2" color="text.secondary">{metric.label}</Typography><Typography variant="h3" sx={{ mt: .75, color: metric.accent, fontWeight: 700 }}>{metric.value}</Typography><Typography variant="caption" color="text.secondary">{metric.detail}</Typography></CardContent></Card>)}</Box><Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', xl: 'minmax(0,1.55fr) minmax(340px,1fr)' }, gap: 2.5 }}><Card><CardContent sx={{ p: 0 }}><Box sx={{ p: 2.5, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}><Box><Typography variant="overline" color="text.secondary">Triage queue</Typography><Typography variant="h6">Recently updated</Typography></Box><Chip label={`${open.length} open`} color="primary" variant="outlined" /></Box><Divider />{reports.length ? reports.slice(0, 6).map((report) => <ReportListRow key={report.id} report={report} onSelect={onSelect}/>) : <EmptyState title="No reports yet" copy="Create the first report to begin triage." />}</CardContent></Card><Card><CardContent><Typography variant="overline" color="text.secondary">Projects</Typography><Typography variant="h6" sx={{ mb: 2.5 }}>Project health</Typography><Stack spacing={2.25}>{projects.length ? projects.map((project) => <Box key={project.id}><Stack direction="row" justifyContent="space-between" alignItems="center" mb={.75}><Stack direction="row" spacing={1} alignItems="center"><Box sx={{ width: 9, height: 9, borderRadius: '50%', bgcolor: project.color }}/><Typography variant="body2">{project.name}</Typography></Stack><Typography variant="body2" color="text.secondary">{project.openReportCount}</Typography></Stack><LinearProgress variant="determinate" value={Math.min(100, Math.max(5, project.openReportCount * 12))} sx={{ height: 7, borderRadius: 99, bgcolor: '#F0EDF2', '& .MuiLinearProgress-bar': { borderRadius: 99, bgcolor: project.color } }}/></Box>) : <EmptyState title="No accessible projects" copy="An administrator can grant access."/>}</Stack></CardContent></Card></Box></>; }
function ReportsView({ reports, onSelect, onCreate }: { reports: Report[]; onSelect: (report: Report) => void; onCreate: () => void }) { return <><PageHeader eyebrow="Customer reports" title="Reports" copy="Search, inspect, and move the issues customers and product teams are tracking." action={<Button variant="contained" startIcon={<AddRounded />} onClick={onCreate}>New report</Button>}/><Paper variant="outlined" sx={{ overflow: 'hidden', borderRadius: 4 }}><Box sx={{ p: 1.5, display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid', borderColor: 'divider', bgcolor: '#FFFBFE' }}><Chip icon={<TuneRounded />} label={`${reports.length} reports`} variant="outlined"/><Typography variant="body2" color="text.secondary" sx={{ alignSelf: 'center' }}>Triage view</Typography></Box><TableContainer sx={{ display: { xs: 'none', md: 'block' } }}><Table><TableHead><TableRow sx={{ bgcolor: '#F6F2FA' }}><TableCell>Report</TableCell><TableCell>Status</TableCell><TableCell>Priority</TableCell><TableCell>Project</TableCell><TableCell>Updated</TableCell><TableCell /></TableRow></TableHead><TableBody>{reports.length ? reports.map((report) => <TableRow hover key={report.id} sx={{ cursor: 'pointer' }} onClick={() => onSelect(report)}><TableCell><Stack direction="row" spacing={1.25} alignItems="flex-start"><PriorityDot priority={report.priority}/><Box><Typography variant="body2">{report.title}</Typography><Typography variant="caption" color="text.secondary">{reportCode(report)} · {report.reporterName}{report.labels?.length ? ` · ${report.labels.join(', ')}` : ''}</Typography></Box></Stack></TableCell><TableCell><StatusChip status={report.status}/></TableCell><TableCell>{priorityLabel(report.priority)}</TableCell><TableCell>{report.projectName}</TableCell><TableCell>{relativeDate(report.updatedAt)}</TableCell><TableCell align="right"><MoreHorizRounded color="action"/></TableCell></TableRow>) : <TableRow><TableCell colSpan={6}><EmptyState title="No reports found" copy="Adjust your search or create a new report."/></TableCell></TableRow>}</TableBody></Table></TableContainer><Stack sx={{ display: { xs: 'flex', md: 'none' } }}>{reports.length ? reports.map((report) => <ReportListRow key={report.id} report={report} onSelect={onSelect} detailed/>) : <EmptyState title="No reports found" copy="Adjust your search or create a new report."/>}</Stack></Paper></>; }
function ReportListRow({ report, onSelect, detailed = false }: { report: Report; onSelect: (report: Report) => void; detailed?: boolean }) { return <CardActionArea component="button" onClick={() => onSelect(report)} sx={{ textAlign: 'left', borderRadius: 0, borderBottom: '1px solid', borderColor: 'divider', '&:last-child': { borderBottom: 0 } }}><Box sx={{ p: detailed ? 2 : 2.25, display: 'flex', alignItems: 'flex-start', gap: 1.25 }}><PriorityDot priority={report.priority}/><Box minWidth={0} flex={1}><Typography variant="body2" noWrap>{report.title}</Typography><Typography variant="caption" color="text.secondary">{reportCode(report)} · {report.projectName} · {report.reporterName}</Typography>{report.labels?.length ? <Stack direction="row" spacing={.5} mt={.75}>{report.labels.slice(0, 2).map((label) => <Chip key={label} label={label} size="small" variant="outlined" sx={{ height: 21 }}/>)}</Stack> : null}</Box><Stack alignItems="flex-end" spacing={.75}><StatusChip status={report.status}/><Typography variant="caption" color="text.secondary">{relativeDate(report.updatedAt)}</Typography></Stack></Box></CardActionArea>; }
function ProjectsView({ projects, onProject }: { projects: Project[]; onProject: (project: Project) => void }) { return <><PageHeader eyebrow="Organization workspace" title="Projects" copy="Projects define the customer and team spaces where reports can be shared and resolved."/><Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: 'repeat(2,minmax(0,1fr))', xl: 'repeat(3,minmax(0,1fr))' }, gap: 2.25 }}>{projects.length ? projects.map((project) => <Card key={project.id}><CardActionArea onClick={() => onProject(project)} sx={{ height: '100%', textAlign: 'left' }}><CardContent sx={{ p: 2.5 }}><Stack direction="row" justifyContent="space-between"><Avatar variant="rounded" sx={{ bgcolor: `${project.color}18`, color: project.color, fontWeight: 700 }}>{project.name.slice(0,1)}</Avatar><ArrowBackRounded sx={{ transform: 'rotate(180deg)', color: 'text.secondary' }}/></Stack><Typography variant="h6" sx={{ mt: 3 }}>{project.name}</Typography><Typography variant="body2" color="text.secondary" sx={{ mt: 1, minHeight: 42 }}>{project.description || 'No project description has been added.'}</Typography><Divider sx={{ my: 2.5 }}/><Typography variant="body2" color="text.secondary"><Box component="span" color="text.primary">{project.openReportCount}</Box> open reports</Typography></CardContent></CardActionArea></Card>) : <EmptyState title="No projects available" copy="Your organization administrator can add a project and assign access."/>}</Box></>; }
function EmptyState({ title, copy }: { title: string; copy: string }) { return <Stack alignItems="center" spacing={1} sx={{ textAlign: 'center', p: 5, color: 'text.secondary' }}><FolderRounded color="primary"/><Typography color="text.primary">{title}</Typography><Typography variant="body2">{copy}</Typography></Stack>; }
function CreateReportDialog({ open, projects, onClose, onCreate }: { open: boolean; projects: Project[]; onClose: () => void; onCreate: (event: FormEvent<HTMLFormElement>) => void }) { const small = useMediaQuery(theme.breakpoints.down('sm')); return <Dialog open={open} onClose={onClose} fullScreen={small} maxWidth="md" fullWidth PaperProps={{ component: 'form', onSubmit: onCreate }}><DialogTitle sx={{ pb: 1 }}>Create report<Typography display="block" variant="body2" color="text.secondary" sx={{ mt: .5 }}>Capture enough context for your team to reproduce and resolve the issue.</Typography></DialogTitle><DialogContent dividers><Stack spacing={2.25} sx={{ pt: 1 }}><TextField required label="Title" name="title" placeholder="What happened?" autoFocus/><Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}><FormControl fullWidth size="small"><InputLabel>Project</InputLabel><Select required name="projectId" label="Project">{projects.map((project) => <MenuItem key={project.id} value={project.id}>{project.name}</MenuItem>)}</Select></FormControl><FormControl fullWidth size="small"><InputLabel>Priority</InputLabel><Select name="priority" defaultValue="medium" label="Priority">{priorityOrder.map((priority) => <MenuItem key={priority} value={priority}>{priorityLabel(priority)}</MenuItem>)}</Select></FormControl></Stack><TextField required label="Description" name="description" placeholder="Explain the problem and its impact." multiline minRows={3}/><TextField label="Steps to reproduce" name="reproductionSteps" placeholder="1. Go to… 2. Click… 3. Observe…" multiline minRows={3}/><Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}><TextField fullWidth label="Expected result" name="expectedResult"/><TextField fullWidth label="Actual result" name="actualResult"/></Stack><Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}><TextField fullWidth label="Browser / device" name="browserDevice" placeholder="Safari on iPhone 15"/><TextField fullWidth label="App version" name="applicationVersion" placeholder="v2.4.0"/></Stack><Button component="label" variant="outlined" startIcon={<UploadFileRounded />} sx={{ alignSelf: 'flex-start' }}>Attach evidence<input hidden name="attachment" type="file"/></Button><Typography variant="caption" color="text.secondary" sx={{ mt: -1.5 }}>One file up to 25 MB. Evidence is stored privately.</Typography></Stack></DialogContent><DialogActions sx={{ p: 2 }}><Button onClick={onClose}>Cancel</Button><Button type="submit" variant="contained" startIcon={<AddRounded />}>Create report</Button></DialogActions></Dialog>; }
function ReportPanel({ report, onClose, onStatus, onComment }: { report: Report | null; onClose: () => void; onStatus: (report: Report, status: Status) => void; onComment: (event: FormEvent<HTMLFormElement>) => void }) { const small = useMediaQuery(theme.breakpoints.down('sm')); return <Drawer anchor="right" open={Boolean(report)} onClose={onClose} PaperProps={{ sx: { width: { xs: '100%', md: 760 }, bgcolor: '#FFFBFE' } }}>{report && <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}><Box sx={{ px: 2, py: 1.5, display: 'flex', alignItems: 'center', borderBottom: '1px solid', borderColor: 'divider' }}><Button startIcon={<ArrowBackRounded />} onClick={onClose}>Back</Button><Box sx={{ flexGrow: 1 }}/><IconButton onClick={onClose} aria-label="Close report"><CloseRounded /></IconButton></Box><Box sx={{ p: { xs: 2.5, sm: 3.5 }, overflow: 'auto', flex: 1 }}><Typography variant="overline" color="text.secondary">{report.projectName} / {reportCode(report)}</Typography><Stack direction="row" spacing={1.25} alignItems="flex-start" mt={1}><PriorityDot priority={report.priority}/><Typography variant="h5">{report.title}</Typography></Stack><Stack direction="row" spacing={1} mt={2} flexWrap="wrap"><StatusChip status={report.status}/><Chip icon={<LockRounded />} label="Customer updates send by email" size="small" variant="outlined"/></Stack><Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: 'minmax(0,1fr) 220px' }, gap: 4, mt: 4 }}><Box><Typography variant="subtitle2">Report details</Typography><Typography color="text.secondary" sx={{ mt: 1, lineHeight: 1.65 }}>This report was submitted by {report.reporterName}. Use a customer-visible comment to share progress, or an internal note to keep discussion inside your team.</Typography><Divider sx={{ my: 3 }}/><Typography variant="subtitle2" sx={{ mb: 1.5 }}>Post an update</Typography><Box component="form" onSubmit={onComment}><TextField fullWidth required multiline minRows={4} label="Update" name="body" placeholder="Write a customer-visible update…"/><RadioGroup row defaultValue="customer" name="visibility" sx={{ mt: 1 }}><FormControlLabel value="customer" control={<Radio size="small"/>} label={<Typography variant="body2">Customer visible</Typography>}/><FormControlLabel value="internal" control={<Radio size="small"/>} label={<Typography variant="body2">Internal only</Typography>}/></RadioGroup><Button type="submit" variant="contained" sx={{ mt: 1.5 }}>Post update</Button></Box></Box><Card variant="outlined" sx={{ height: 'fit-content', bgcolor: '#F6F2FA' }}><CardContent><Typography variant="overline" color="text.secondary">Properties</Typography><Stack spacing={2} mt={1.5}><FormControl fullWidth size="small"><InputLabel>Status</InputLabel><Select value={report.status} label="Status" onChange={(event) => onStatus(report, event.target.value as Status)}>{statusOrder.map((status) => <MenuItem key={status} value={status}>{statusLabel(status)}</MenuItem>)}</Select></FormControl><Property label="Priority" value={priorityLabel(report.priority)}/><Property label="Project" value={report.projectName}/><Property label="Reporter" value={report.reporterName}/><Property label="Updated" value={relativeDate(report.updatedAt)}/>{report.dueAt && <Property label="Due" value={new Date(report.dueAt).toLocaleDateString()}/>}</Stack></CardContent></Card></Box></Box></Box>}</Drawer>; }
function Property({ label, value }: { label: string; value: string }) { return <Box><Typography variant="caption" color="text.secondary" sx={{ textTransform: 'uppercase', letterSpacing: '.08em' }}>{label}</Typography><Typography variant="body2" sx={{ mt: .25 }}>{value}</Typography></Box>; }


type ReportDetailPayload = {
  report: Report & {
    description: string; reproduction_steps?: string | null; expected_result?: string | null; actual_result?: string | null;
    browser_device?: string | null; application_version?: string | null; reporterName?: string; assigneeName?: string | null;
  };
  comments: Array<{ id: string; body: string; visibility: 'customer' | 'internal'; createdAt: string; authorName: string }>;
  attachments: Array<{ id: string; originalFilename: string; contentType: string; byteSize: number; createdAt: string }>;
  labels: Array<{ id: string; name: string; color: string }>;
  duplicates: Array<{ id: string; sequenceNumber: number; title: string; status: Status }>;
};

/**
 * The detail drawer deliberately keeps content primary and properties secondary. It is an
 * original BugFlow implementation inspired by the concise issue-detail workflow observed
 * in the authorized reference workspace.
 */
function LiveReportPanel({ report, onClose, onStatus, onSaved }: { report: Report | null; onClose: () => void; onStatus: (report: Report, status: Status) => Promise<void>; onSaved: () => Promise<void> }) {
  const small = useMediaQuery(theme.breakpoints.down('sm'));
  const [detail, setDetail] = useState<ReportDetailPayload | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const loadDetail = async () => {
    if (!report) return;
    setError('');
    try { setDetail(await api<ReportDetailPayload>(`/api/reports/${report.id}`)); }
    catch (err) { setError(err instanceof Error ? err.message : 'Unable to load report details.'); }
  };
  useEffect(() => { void loadDetail(); }, [report?.id]);
  const updateReport = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!report) return;
    setBusy(true); setError('');
    const form = new FormData(event.currentTarget);
    try {
      await api(`/api/reports/${report.id}`, { method: 'PATCH', body: JSON.stringify({ title: String(form.get('title')), description: String(form.get('description')), reproductionSteps: String(form.get('reproductionSteps') || '') || null, expectedResult: String(form.get('expectedResult') || '') || null, actualResult: String(form.get('actualResult') || '') || null, browserDevice: String(form.get('browserDevice') || '') || null, applicationVersion: String(form.get('applicationVersion') || '') || null, priority: String(form.get('priority')), dueAt: form.get('dueAt') ? new Date(String(form.get('dueAt'))).toISOString() : null }) });
      await Promise.all([loadDetail(), onSaved()]);
    } catch (err) { setError(err instanceof Error ? err.message : 'Unable to save report changes.'); }
    finally { setBusy(false); }
  };
  const patchProperties = async (patch: Record<string, unknown>) => {
    if (!report) return;
    setBusy(true); setError('');
    try { await api(`/api/reports/${report.id}`, { method: 'PATCH', body: JSON.stringify(patch) }); await Promise.all([loadDetail(), onSaved()]); }
    catch (err) { setError(err instanceof Error ? err.message : 'Unable to update report properties.'); }
    finally { setBusy(false); }
  };
  const addComment = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!report) return;
    const form = new FormData(event.currentTarget); const body = String(form.get('body') ?? '').trim(); if (!body) return;
    setBusy(true); setError('');
    try { await api(`/api/reports/${report.id}/comments`, { method: 'POST', body: JSON.stringify({ body, visibility: form.get('visibility') === 'internal' ? 'internal' : 'customer' }) }); (event.currentTarget as HTMLFormElement).reset(); await loadDetail(); }
    catch (err) { setError(err instanceof Error ? err.message : 'Unable to post comment.'); }
    finally { setBusy(false); }
  };
  const downloadAttachment = async (attachmentId: string) => {
    try { const result = await api<{ url: string }>(`/api/attachments/${attachmentId}/download`); window.open(result.url, '_blank', 'noopener,noreferrer'); }
    catch (err) { setError(err instanceof Error ? err.message : 'Unable to open attachment.'); }
  };
  return <Drawer anchor="right" open={Boolean(report)} onClose={onClose} PaperProps={{ sx: { width: { xs: '100%', lg: 1000 }, bgcolor: '#FFFBFE' } }}>
    <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
      <Box sx={{ minHeight: 64, px: { xs: 1, sm: 2 }, display: 'flex', alignItems: 'center', gap: 1, borderBottom: '1px solid', borderColor: 'divider' }}>
        <Button startIcon={<ArrowBackRounded />} onClick={onClose}>Back</Button><Typography variant="body2" color="text.secondary" sx={{ ml: 1 }}>{report ? reportCode(report) : ''}</Typography><Box flex={1}/><Tooltip title="Copy report link"><IconButton onClick={() => report && navigator.clipboard?.writeText(`${window.location.origin}/?report=${report.id}`)}><DescriptionRounded fontSize="small"/></IconButton></Tooltip><IconButton onClick={onClose} aria-label="Close report"><CloseRounded /></IconButton>
      </Box>
      {!detail && !error && <Box sx={{ p: 5, display: 'grid', placeItems: 'center' }}><CircularProgress /></Box>}
      {error && <Alert severity="error" sx={{ m: 2 }}>{error}</Alert>}
      {detail && <Box sx={{ overflowY: 'auto', flex: 1, p: { xs: 2, sm: 3 }, display: 'grid', gridTemplateColumns: { xs: '1fr', md: 'minmax(0,1fr) 250px' }, gap: { xs: 3, md: 4 } }}>
        <Stack spacing={3}>
          <Stack component="form" onSubmit={updateReport} spacing={3}>
          <Box><Typography variant="overline" color="primary.main">{reportCode(detail.report)} · {detail.report.projectName}</Typography><TextField name="title" defaultValue={detail.report.title} variant="standard" fullWidth inputProps={{ 'aria-label': 'Report title' }} sx={{ mt: .5, '& input': { fontSize: { xs: 26, sm: 32 }, fontWeight: 700, letterSpacing: '-.03em', lineHeight: 1.18 } }}/></Box>
          <TextField name="description" defaultValue={detail.report.description} label="Description" required multiline minRows={3} fullWidth />
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}><TextField name="reproductionSteps" defaultValue={detail.report.reproduction_steps ?? ''} label="Steps to reproduce" multiline minRows={3} fullWidth/><TextField name="expectedResult" defaultValue={detail.report.expected_result ?? ''} label="Expected result" multiline minRows={3} fullWidth/></Stack>
          <TextField name="actualResult" defaultValue={detail.report.actual_result ?? ''} label="Actual result" multiline minRows={2} fullWidth/>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}><TextField name="browserDevice" defaultValue={detail.report.browser_device ?? ''} label="Browser / device" fullWidth/><TextField name="applicationVersion" defaultValue={detail.report.application_version ?? ''} label="App version" fullWidth/></Stack>
          <Stack direction="row" justifyContent="flex-end"><Button type="submit" variant="outlined" disabled={busy}>{busy ? 'Saving…' : 'Save changes'}</Button></Stack>
          </Stack>
          <Divider/>
          <Box><Typography variant="overline" color="text.secondary">Evidence</Typography><Stack spacing={1} sx={{ mt: 1 }}>{detail.attachments.length ? detail.attachments.map((attachment) => <Card variant="outlined" key={attachment.id}><CardActionArea onClick={() => void downloadAttachment(attachment.id)}><CardContent sx={{ py: 1.25, '&:last-child': { pb: 1.25 }, display: 'flex', alignItems: 'center', gap: 1.25 }}><UploadFileRounded color="primary" fontSize="small"/><Box flex={1}><Typography variant="body2">{attachment.originalFilename}</Typography><Typography variant="caption" color="text.secondary">{Math.ceil(attachment.byteSize / 1024)} KB · {relativeDate(attachment.createdAt)}</Typography></Box></CardContent></CardActionArea></Card>) : <Typography variant="body2" color="text.secondary">No attachments added.</Typography>}</Stack></Box>
          <Divider/>
          <Box><Typography variant="overline" color="text.secondary">Activity</Typography><Stack spacing={1.5} sx={{ mt: 1.25 }}>{detail.comments.length ? detail.comments.map((comment) => <Box key={comment.id} sx={{ p: 1.5, borderRadius: 3, bgcolor: comment.visibility === 'internal' ? '#FFF8E1' : '#F6F2FA', border: '1px solid', borderColor: comment.visibility === 'internal' ? '#FFE08A' : 'divider' }}><Stack direction="row" justifyContent="space-between" gap={1}><Typography variant="body2" fontWeight={700}>{comment.authorName}</Typography><Stack direction="row" spacing={1}><Chip label={comment.visibility === 'internal' ? 'Internal' : 'Customer'} size="small" color={comment.visibility === 'internal' ? 'warning' : 'default'}/><Typography variant="caption" color="text.secondary">{relativeDate(comment.createdAt)}</Typography></Stack></Stack><Typography variant="body2" sx={{ mt: .75, whiteSpace: 'pre-wrap' }}>{comment.body}</Typography></Box>) : <Typography variant="body2" color="text.secondary">No activity yet.</Typography>}</Stack>
            <Stack component="form" onSubmit={addComment} spacing={1.25} sx={{ mt: 2 }}><TextField name="body" label="Add an update" multiline minRows={2} fullWidth/><Stack direction="row" spacing={1} justifyContent="space-between"><FormControl size="small" sx={{ minWidth: 150 }}><InputLabel>Visibility</InputLabel><Select name="visibility" label="Visibility" defaultValue="customer"><MenuItem value="customer">Customer visible</MenuItem><MenuItem value="internal">Internal only</MenuItem></Select></FormControl><Button type="submit" variant="contained" disabled={busy}>Post update</Button></Stack></Stack>
          </Box>
        </Stack>
        <Stack spacing={2.25} sx={{ alignSelf: 'start', position: { md: 'sticky' }, top: 0 }}>
          <Card variant="outlined"><CardContent sx={{ p: 2 }}><Typography variant="overline" color="text.secondary">Properties</Typography><Stack spacing={2} sx={{ mt: 1.5 }}>
            <FormControl size="small" fullWidth><InputLabel>Status</InputLabel><Select label="Status" value={detail.report.status} onChange={(event) => { if (report) void onStatus(report, event.target.value as Status).then(loadDetail); }}>{statusOrder.map((status) => <MenuItem key={status} value={status}>{statusLabel(status)}</MenuItem>)}</Select></FormControl>
            <FormControl size="small" fullWidth><InputLabel>Priority</InputLabel><Select label="Priority" value={detail.report.priority} onChange={(event) => void patchProperties({ priority: event.target.value })}><MenuItem value="low">Low</MenuItem><MenuItem value="medium">Medium</MenuItem><MenuItem value="high">High</MenuItem><MenuItem value="critical">Critical</MenuItem></Select></FormControl>
            <TextField label="Due date" type="datetime-local" value={detail.report.dueAt ? new Date(detail.report.dueAt).toISOString().slice(0,16) : ''} onChange={(event) => { if (event.target.value) void patchProperties({ dueAt: new Date(event.target.value).toISOString() }); }} InputLabelProps={{ shrink: true }} />
            <Property label="Assignee" value={detail.report.assigneeName ?? 'Unassigned'} /><Property label="Reporter" value={detail.report.reporterName ?? detail.report.reporterName ?? 'Unknown'} /><Property label="Project" value={detail.report.projectName} />
          </Stack></CardContent></Card>
          <Card variant="outlined"><CardContent sx={{ p: 2 }}><Typography variant="overline" color="text.secondary">Labels</Typography><Stack direction="row" flexWrap="wrap" gap={.75} sx={{ mt: 1 }}>{detail.labels.length ? detail.labels.map((label) => <Chip key={label.id} label={label.name} size="small" sx={{ bgcolor: `${label.color}18`, color: label.color, fontWeight: 700 }}/>) : <Typography variant="body2" color="text.secondary">No labels</Typography>}</Stack></CardContent></Card>
          {detail.duplicates.length ? <Card variant="outlined"><CardContent sx={{ p: 2 }}><Typography variant="overline" color="text.secondary">Related reports</Typography>{detail.duplicates.map((item) => <Box key={item.id} sx={{ mt: 1 }}><Typography variant="body2">BF-{item.sequenceNumber} · {item.title}</Typography><StatusChip status={item.status}/></Box>)}</CardContent></Card> : null}
        </Stack>
      </Box>}
    </Box>
  </Drawer>;
}


function EnhancedReportsView({ reports, onSelect, onCreate }: { reports: Report[]; onSelect: (report: Report) => void; onCreate: () => void }) {
  const [statusFilter, setStatusFilter] = useState<'all' | Status>('all');
  const [priorityFilter, setPriorityFilter] = useState<'all' | Priority>('all');
  const [compact, setCompact] = useState(false);
  const [collapsed, setCollapsed] = useState<Partial<Record<Status, boolean>>>({});
  const filtered = useMemo(() => reports.filter((report) => (statusFilter === 'all' || report.status === statusFilter) && (priorityFilter === 'all' || report.priority === priorityFilter)), [reports, statusFilter, priorityFilter]);
  const grouped = statusOrder.map((status) => ({ status, reports: filtered.filter((report) => report.status === status) })).filter((group) => group.reports.length > 0);
  return <>
    <PageHeader eyebrow="Customer reports" title="Reports" copy="Filter, group, and triage reports without losing customer context." action={<Button variant="contained" startIcon={<AddRounded />} onClick={onCreate}>New report</Button>}/>
    <Paper variant="outlined" sx={{ overflow: 'hidden', borderRadius: 4 }}>
      <Stack direction={{ xs: 'column', md: 'row' }} alignItems={{ md: 'center' }} gap={1.25} sx={{ p: 1.5, borderBottom: '1px solid', borderColor: 'divider', bgcolor: '#FFFBFE' }}>
        <Chip icon={<TuneRounded />} label={`${filtered.length} reports`} variant="outlined" />
        <Stack direction="row" gap={1} flexWrap="wrap" flex={1}>
          <FormControl size="small" sx={{ minWidth: 150 }}><InputLabel>Status</InputLabel><Select label="Status" value={statusFilter} onChange={(event) => setStatusFilter(event.target.value as 'all' | Status)}><MenuItem value="all">All statuses</MenuItem>{statusOrder.map((status) => <MenuItem key={status} value={status}>{statusLabel(status)}</MenuItem>)}</Select></FormControl>
          <FormControl size="small" sx={{ minWidth: 145 }}><InputLabel>Priority</InputLabel><Select label="Priority" value={priorityFilter} onChange={(event) => setPriorityFilter(event.target.value as 'all' | Priority)}><MenuItem value="all">All priorities</MenuItem>{priorityOrder.map((priority) => <MenuItem key={priority} value={priority}>{priorityLabel(priority)}</MenuItem>)}</Select></FormControl>
        </Stack>
        <Button size="small" variant="text" onClick={() => setCompact((value) => !value)}>{compact ? 'Comfortable density' : 'Compact density'}</Button>
      </Stack>
      {grouped.length ? grouped.map((group) => <Box key={group.status}>
        <Box sx={{ px: compact ? 1.5 : 2, py: 1, display: 'flex', alignItems: 'center', gap: 1, bgcolor: '#F6F2FA', borderBottom: '1px solid', borderColor: 'divider' }}><Button size="small" onClick={() => setCollapsed((value) => ({ ...value, [group.status]: !value[group.status] }))}>{collapsed[group.status] ? 'Expand' : 'Collapse'}</Button><StatusChip status={group.status}/><Typography variant="body2" color="text.secondary">{group.reports.length}</Typography></Box>
        {!collapsed[group.status] && <TableContainer sx={{ display: { xs: 'none', md: 'block' } }}><Table size={compact ? 'small' : 'medium'}><TableBody>{group.reports.map((report) => <TableRow hover key={report.id} sx={{ cursor: 'pointer' }} onClick={() => onSelect(report)}><TableCell sx={{ width: 34 }}><PriorityDot priority={report.priority}/></TableCell><TableCell><Typography variant="body2">{report.title}</Typography><Typography variant="caption" color="text.secondary">{reportCode(report)} · {report.reporterName}{report.assigneeName ? ` · ${report.assigneeName}` : ''}</Typography></TableCell><TableCell><Chip size="small" label={priorityLabel(report.priority)} variant="outlined"/></TableCell><TableCell>{report.projectName}</TableCell><TableCell>{report.dueAt ? new Date(report.dueAt).toLocaleDateString() : '—'}</TableCell><TableCell align="right"><MoreHorizRounded color="action"/></TableCell></TableRow>)}</TableBody></Table></TableContainer>}
        {!collapsed[group.status] && <Stack sx={{ display: { xs: 'flex', md: 'none' } }}>{group.reports.map((report) => <ReportListRow key={report.id} report={report} onSelect={onSelect} detailed/>)}</Stack>}
      </Box>) : <EmptyState title="No reports match these filters" copy="Try a different status or priority, or create a new report."/>}
    </Paper>
  </>;
}
